    /**
     * Method to retrieve the Document via DocumentFetchOneSummary
     * @param 	summary DocumentFetchOneSummary 
     * @return 	DocumentFetchOneResponse
     * @exception ProcessingException - Thrown if processing any related problems
     * @exception IllegalArgumentException 
     */
    public Document getDocument( DocumentFetchOneSummary summary ) 
    throws ProcessingException, IllegalArgumentException {
    	
    	if( summary == null )
    		throw new IllegalArgumentException( "DocumentFetchOneSummary arg cannot be null" );
    	
    	Document entity = null;
    	
        try {
        	// --------------------------------------
        	// validate the fetch one summary
        	// --------------------------------------    	
        	validator.validate( summary );    
        	
        	// --------------------------------------
        	// use queryGateway to send request to Find a Document
        	// --------------------------------------
        	CompletableFuture<Document> futureEntity = queryGateway.query(new FindDocumentQuery( new LoadDocumentFilter( summary.getDocumentId() ) ), ResponseTypes.instanceOf(Document.class));
        	
        	entity = futureEntity.get();
        }
        catch( Exception exc ) {
            final String errMsg = "Unable to locate Document with id " + summary.getDocumentId();
            LOGGER.log( Level.WARNING, errMsg, exc );
            throw new ProcessingException( errMsg, exc );
        }
        finally {
        }        
        
        return entity;
    }


